from __future__ import annotations

import calendar
import re
import time
from datetime import datetime
from typing import Optional

TS_FORMAT = "%Y-%m-%dT%H:%M:%SZ"
_TS_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z")


class Clock:
    """Real clock (floor of time.time()) or a fake clock frozen at an instant."""

    def __init__(self, fake_now: Optional[int] = None) -> None:
        self._fake: Optional[int] = fake_now

    @property
    def is_fake(self) -> bool:
        return self._fake is not None

    def now(self) -> int:
        if self._fake is not None:
            return self._fake
        return int(time.time() // 1)

    def set(self, ts: int) -> None:
        if self._fake is None:
            raise RuntimeError("set() is only valid on a fake clock")
        self._fake = ts


def parse_ts(s: str) -> int:
    if not isinstance(s, str) or not _TS_RE.fullmatch(s):
        raise ValueError("invalid timestamp")
    try:
        return calendar.timegm(datetime.strptime(s, TS_FORMAT).timetuple())
    except (ValueError, OverflowError, OSError) as e:
        raise ValueError("invalid timestamp") from e


def format_ts(n: int) -> str:
    try:
        return time.strftime(TS_FORMAT, time.gmtime(n))
    except (ValueError, OverflowError, OSError, TypeError) as e:
        raise ValueError("timestamp out of range") from e
