from __future__ import annotations

import pytest

from linkvault.clock import Clock, format_ts, parse_ts


def test_epoch_and_roundtrip():
    assert parse_ts("1970-01-01T00:00:00Z") == 0
    for n in (0, 1, 1700000000, 4102444800):
        assert parse_ts(format_ts(n)) == n
    assert format_ts(1700000000) == "2023-11-14T22:13:20Z"


@pytest.mark.parametrize("bad", [
    "1970-01-01T00:00:00+00:00", "1970-01-01T00:00:00.5Z", "garbage", "",
    "1970-1-1T0:0:0Z", " 1970-01-01T00:00:00Z", "1970-01-01T00:00:00Z\n",
    "1970-01-01 00:00:00Z", "1970-13-01T00:00:00Z", "0000-01-01T00:00:00Z",
    "9999-99-99T99:99:99Z", None, 5,
])
def test_parse_invalid(bad):
    with pytest.raises(ValueError):
        parse_ts(bad)


def test_format_out_of_range():
    with pytest.raises(ValueError):
        format_ts(10 ** 30)


def test_fake_clock_frozen_until_set():
    c = Clock(100)
    assert c.is_fake and c.now() == 100 and c.now() == 100
    c.set(50)
    assert c.now() == 50


def test_real_clock_int():
    c = Clock()
    assert not c.is_fake
    assert isinstance(c.now(), int)
    with pytest.raises(RuntimeError):
        c.set(1)
